// === Tab: mySketch ===
const 木 = (x, y, z) => ({
  x: random(width) - width / 2,
  y: random(height / 2),
  z: random(5),
});

const 林 = {
  林: [],

  初期化() {
    for (let i = 100; i--; ) {
      this.林.push(木());
    }
  },

  更新() {
    for (const 木 of this.林) {
      木.x -= ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2) * 0.025;
      if (木.x > width / 2) 木.x = -width / 2;
      if (木.x < -width / 2) 木.x = width / 2;
      const my = constrain((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height);
      木.z -= log(1 + my) / 200;
      if (木.z < 0) 木.z = 5;
    }
    this.林.sort((木1, 木2) => (木1.z > 木2.z ? -1 : 1));
  },

  影を描く() {
    fill('black');
    noStroke();
    for (const 木 of this.林) {
      rect(木.x / 木.z, 50 / 木.z, (-木.y / 木.z) * 0.6, -2);
    }
  },

  林を描く() {
    fill('white');
    stroke('black');
    for (const 木 of this.林) {
      rect(木.x / 木.z, 50 / 木.z, 16 / 木.z, -木.y / 木.z);
    }
  },

};

setup = () => {
  createCanvas(900, 600);
  林.初期化();
};

draw = (_) => {
  background('white');
  translate(width / 2, height / 2);
  林.更新();
  林.影を描く();
  林.林を描く();
};
